# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(8 * 60 + 53, 17 * 60 + 8)]
        self.assertEqual(round_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        self.assertEqual(round_labels([Span(7, 20)], 15), ["00:00-00:15 (0h 15m)"])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)
